create table public.cab_meetings(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,title text not null check(length(trim(title)) between 5 and 240),scheduled_at timestamptz not null,notes text,created_by uuid not null references public.user_profiles(id) on delete restrict,created_at timestamptz not null default now());
create table public.cab_change_items(id uuid primary key default gen_random_uuid(),cab_meeting_id uuid not null references public.cab_meetings(id) on delete restrict,change_id uuid not null references public.changes(id) on delete restrict,decision text not null default 'PENDING' check(decision in('PENDING','APPROVED','REJECTED','DEFERRED')),comment text,unique(cab_meeting_id,change_id));
create table public.change_pirs(id uuid primary key default gen_random_uuid(),change_id uuid not null unique references public.changes(id) on delete restrict,organization_id uuid not null references public.organizations(id) on delete restrict,outcome text not null check(outcome in('SUCCESS','PARTIAL','FAILED')),expected_result text not null check(length(trim(expected_result)) between 10 and 10000),actual_result text not null check(length(trim(actual_result)) between 10 and 10000),rollback_performed boolean not null default false,lessons_learned text,created_by uuid not null references public.user_profiles(id) on delete restrict,created_at timestamptz not null default now());
alter table public.cab_meetings enable row level security;alter table public.cab_change_items enable row level security;alter table public.change_pirs enable row level security;create policy "management reads cab meetings" on public.cab_meetings for select to authenticated using(public.has_ticket_management_role(organization_id));create policy "management reads cab items" on public.cab_change_items for select to authenticated using(exists(select 1 from public.cab_meetings m where m.id=cab_meeting_id and public.has_ticket_management_role(m.organization_id)));create policy "management reads pirs" on public.change_pirs for select to authenticated using(public.has_ticket_management_role(organization_id));
create or replace function public.create_change_pir(target_change_id uuid,target_outcome text,target_expected text,target_actual text,target_rollback boolean,target_lessons text default null) returns uuid language plpgsql security definer set search_path=public as $$ declare c public.changes%rowtype;pir_id uuid;begin select * into c from public.changes where id=target_change_id for update;if c.id is null or not public.has_ticket_management_role(c.organization_id) then raise exception 'PIR_NOT_AUTHORIZED';end if;if target_outcome not in('SUCCESS','PARTIAL','FAILED') or length(trim(target_expected)) not between 10 and 10000 or length(trim(target_actual)) not between 10 and 10000 then raise exception 'PIR_INVALID_INPUT';end if;insert into public.change_pirs(change_id,organization_id,outcome,expected_result,actual_result,rollback_performed,lessons_learned,created_by) values(c.id,c.organization_id,target_outcome,trim(target_expected),trim(target_actual),target_rollback,nullif(trim(target_lessons),''),auth.uid()) returning id into pir_id;insert into public.entity_relationships(organization_id,source_entity_type,source_entity_id,target_entity_type,target_entity_id,relationship_type,reason,created_by) values(c.organization_id,'CHANGE',c.id,'PIR',pir_id,'REVIEWED_BY','PIR registrada.',auth.uid());insert into public.audit_logs(organization_id,actor_id,action,entity_type,entity_id,after_value,source) values(c.organization_id,auth.uid(),'CHANGE_PIR_CREATED','change_pir',pir_id,jsonb_build_object('change_id',c.id,'outcome',target_outcome),'WEB');return pir_id;end;$$;revoke all on function public.create_change_pir(uuid,text,text,text,boolean,text) from public;grant execute on function public.create_change_pir(uuid,text,text,text,boolean,text) to authenticated;
